export type AppPrismaClientOptions = Prisma.PrismaClientOptions & {
    log: Array<Prisma.LogLevel | Prisma.LogDefinition>
    omit?: never
}

const basePrismaClient = new PrismaClient<AppPrismaClientOptions, "query", undefined>({
    adapter: createPrismaAdapter(),
    log: [{ level: "query", emit: "event" }],
})

type LimitableClient = Pick<PrismaClient<never, undefined>, "$extends">
